    <div id="app"></div>

    <script>
      const quizQuestions = [
        {
          id: "q1",
          number: "Question 1",
          title: "Which of these are commonly used for front-end web development?",
          helpText: "Select all answers that are widely used to build interactive experiences in the browser.",
          choices: ["JavaScript", "TypeScript", "Python", "Rust"]
        },
        {
          id: "q2",
          number: "Question 2",
          title: "Which of these languages are often used for systems programming?",
          choices: ["C", "Rust", "Ruby", "C++"]
        },
        {
          id: "q3",
          number: "Question 3",
          title: "Which of these languages are typically used for data analysis or scientific computing?",
          choices: ["Python", "R", "Go", "Julia"]
        }
      ];

      const state = {
        selections: Object.fromEntries(quizQuestions.map((question) => [question.id, []])),
        submitted: false
      };

      function escapeHtml(value) {
        return value
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      function ChoiceOption(questionId, choice) {
        const checked = state.selections[questionId].includes(choice);

        return `
          <label class="choice">
            <input
              type="checkbox"
              name="${questionId}"
              value="${escapeHtml(choice)}"
              ${checked ? "checked" : ""}
              onchange="handleChoiceToggle('${questionId}', '${choice.replaceAll("'", "\\'")}')"
            />
            <span>${escapeHtml(choice)}</span>
          </label>
        `;
      }

      function QuizQuestion(question) {
        return `
          <div class="form-field">
            <div class="question-meta">${question.number}</div>
            <h2 class="question-title">${escapeHtml(question.title)}</h2>
            ${
              question.helpText
                ? `<p class="help-text">${escapeHtml(question.helpText)}</p>`
                : ""
            }
            <div class="choices">
              ${question.choices.map((choice) => ChoiceOption(question.id, choice)).join("")}
            </div>
          </div>
        `;
      }

      function SubmitMessage() {
        if (!state.submitted) {
          return "";
        }

        const totalSelected = Object.values(state.selections).reduce(
          (count, values) => count + values.length,
          0
        );

        return totalSelected
          ? `Submitted with ${totalSelected} selected answer${totalSelected === 1 ? "" : "s"}.`
          : "Submitted with no answers selected.";
      }

      function App() {
        return `
          <main class="app-shell">
            <header class="app-header">
              <div class="eyebrow">Multi-select quiz</div>
              <h1>Computer Languages Quiz</h1>
              <p class="subtitle">
                Explore three quick questions about programming languages. Each question supports multiple selections.
              </p>
            </header>
            <form onsubmit="handleSubmit(event)">
              ${quizQuestions.map(QuizQuestion).join("")}
              <div class="actions">
                <button type="submit">Submit Quiz</button>
                <div class="result" aria-live="polite">${SubmitMessage()}</div>
              </div>
            </form>
          </main>
        `;
      }

      function render() {
        document.getElementById("app").innerHTML = App();
      }

      function handleChoiceToggle(questionId, choice) {
        const selections = new Set(state.selections[questionId]);

        if (selections.has(choice)) {
          selections.delete(choice);
        } else {
          selections.add(choice);
        }

        state.selections[questionId] = [...selections];
        render();
      }

      function handleSubmit(event) {
        event.preventDefault();
        state.submitted = true;
        render();
      }

      window.handleChoiceToggle = handleChoiceToggle;
      window.handleSubmit = handleSubmit;

